class Piece:
    def __init__(self, diagonal, straight, initial_position):
        self.diagonal = diagonal
        self.straight = straight
        self.initial_position = initial_position

    def check_move(self, target_position):
        self.target_position = target_position
        self.row_diff = self.target_position[0] - self.initial_position[0]
        if abs(self.row_diff) > 3:
            return False
        self.col_diff = self.target_position[1] - self.initial_position[1]
        if abs(self.col_diff) > 3:
            return False

        if self.diagonal and (not self.straight):
            return abs(self.row_diff) == abs(self.col_diff)
        if self.straight and (not self.diagonal):
            return abs(self.row_diff) == 0 or abs(self.col_diff) == 0
        if self.straight and self.diagonal:
            return (abs(self.row_diff) == abs(self.col_diff)) or (abs(self.row_diff) == 0 or abs(self.col_diff) == 0)
